-- powerPlus 자산 시드 (phpMyAdmin SQL 탭에 붙여넣기)
-- DB: powerplus (이미 선택된 상태에서 실행)

CREATE TABLE IF NOT EXISTS assets (
  id        VARCHAR(64)  NOT NULL PRIMARY KEY,
  name      VARCHAR(255) NOT NULL,
  category  VARCHAR(32)  NOT NULL,
  tags      JSON         NOT NULL,
  svg       MEDIUMTEXT   NOT NULL,
  INDEX idx_category (category)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO assets (id, name, category, tags, svg) VALUES ('ic-arrow-up', '상승 화살표', 'icon', '["화살표","상승","증가","비즈니스"]', '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" width="100" height="100"><g fill="none" stroke="#16a34a" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"><path d="M50 78 L50 26 M30 46 L50 24 L70 46"/></g></svg>')
  ON DUPLICATE KEY UPDATE name=VALUES(name), category=VALUES(category), tags=VALUES(tags), svg=VALUES(svg);
